custom_css:
:root {
  --zenith-accent: #f5c451;
  --zenith-accent-2: #ffe08a;
}
a, .mes_text a { color: var(--zenith-accent-2); }
::selection { background: rgba(245, 196, 81, 0.35); }
input[type=checkbox], input[type=radio], input[type=range], progress { accent-color: var(--zenith-accent); }
.menu_button:hover, .list-group-item:hover, .menu_button.menu_button_icon:hover { background-color: rgba(245, 196, 81, 0.18); }
.drawer-icon:hover, .drawer-icon.openIcon, #send_but:hover, #options_button:hover, #extensionsMenuButton:hover, .mes_button:hover { color: var(--zenith-accent); filter: none; opacity: 1; }
.text_pole:focus, textarea:focus, select:focus, #send_textarea:focus { border-color: rgba(245, 196, 81, 0.55); outline: none; box-shadow: 0 0 0 1px rgba(245, 196, 81, 0.25); }
::-webkit-scrollbar-thumb { background-color: rgba(245, 196, 81, 0.35); }
::-webkit-scrollbar-thumb:hover { background-color: rgba(245, 196, 81, 0.6); }
.mes.last_mes .mes_block, #chat .mes[is_user='true'] .mes_block { border-color: rgba(245, 196, 81, 0.25); }
